function showProductEditor(serviceId){
  const item=state.catalog.services.find((value)=>value.id===serviceId),target=$(`#product-config-${serviceId}`);
  target.innerHTML=`<form>${field('Name','name','text',true,item.name)}${field('Description','description','text',false,item.description)}<label><input name="enabled" type="checkbox" ${item.enabled?'checked':''}> Available</label><label><input name="trial_enabled" type="checkbox" ${item.trial_enabled?'checked':''}> Trial eligible</label><button>Save product</button></form>`;
  target.querySelector('form').onsubmit=async(event)=>{event.preventDefault();try{await send(`admin/products/${serviceId}`,'PATCH',formValues(event.target));notice('Product updated');load()}catch(error){notice(error.message)}};
}
function showPlanEditor(planId){
  const item=state.catalog.plans.find((value)=>value.id===planId),target=$(`#product-config-${item.service_id}`);
  target.innerHTML=`<form data-toman="true">${field('Name','name','text',true,item.name)}${field('Duration hours','duration_hours','number',true,item.duration_hours)}${field('Traffic GB','traffic_gb','number',false,item.traffic_gb??'')}${field('Concurrent IP limit','user_limit','number',true,item.user_limit)}${field('Wallet price (Toman)','price_minor','number',true,item.price_minor/10)}${field('Stars price XTR','stars_price','number',false,item.stars_price??'')}${field('Crypto price USD cents','usd_price_cents','number',false,item.usd_price_cents??'')}<label><input name="enabled" type="checkbox" ${item.enabled?'checked':''}> Available</label><label><input name="free_purchase_enabled" type="checkbox" ${item.free_purchase_enabled?'checked':''}> One free purchase per customer</label><button>Save plan</button></form>`;
  target.querySelector('form').onsubmit=async(event)=>{event.preventDefault();const values=formValues(event.target);for(const key of Object.keys(values))if(values[key]===null)delete values[key];try{await send(`admin/plans/${planId}`,'PATCH',values);notice('Plan updated');load()}catch(error){notice(error.message)}};
}
async function showInbounds(panelId) {
  try {
    const rows=await api(`admin/panels/${panelId}/inbounds`), target=$(`#inbounds-${panelId}`);
    target.innerHTML=rows.map((inbound)=>`<div class="row"><div><strong>#${inbound.remote_id} ${escapeHtml(inbound.remark)}</strong><br><small>${escapeHtml(inbound.protocol)} · ${inbound.remote_enabled?'Panel enabled':'Panel disabled'}</small></div><label><input type="checkbox" data-allow-inbound="${inbound.id}" ${inbound.allowed?'checked':''}> Available to Alart</label></div>`).join('')||'<p class="empty">No inbounds discovered</p>';
    target.querySelectorAll('[data-allow-inbound]').forEach((input)=>input.onchange=async()=>{try{await send(`admin/inbounds/${input.dataset.allowInbound}/allowed`,'PUT',{allowed:input.checked});notice('Inbound availability saved')}catch(error){input.checked=!input.checked;notice(error.message)}});
  } catch (error) { notice(error.message); }
}
async function showMapping(serviceId) {
  try {
    const [current,...lists]=await Promise.all([api(`admin/services/${serviceId}/mappings`),...state.panels.map((panel)=>api(`admin/panels/${panel.id}/inbounds`))]);
    const selected=new Set(current.map((row)=>row.inbound_id));
    const rows=lists.flatMap((items,index)=>items.filter((item)=>item.allowed&&item.remote_enabled).map((item)=>({...item,panel:state.panels[index].name})));
    const target=$(`#product-config-${serviceId}`);
    target.innerHTML=`<form class="mapping-form">${rows.map((row)=>`<label class="map-option"><input type="checkbox" value="${row.id}" ${selected.has(row.id)?'checked':''}>${escapeHtml(row.panel)} · ${escapeHtml(row.remark)} (#${row.remote_id})</label>`).join('')||'<p>No allowed inbounds. Enable them in Panels first.</p>'}<button>Save mapping</button></form>`;
    target.querySelector('form').onsubmit=async(event)=>{event.preventDefault();const ids=[...target.querySelectorAll('input:checked')].map((input)=>Number(input.value));try{await send(`admin/services/${serviceId}/mappings`,'PUT',{inbound_ids:ids});notice('Product mapping saved')}catch(error){notice(error.message)}};
  } catch (error) { notice(error.message); }
}
async function showPricing(serviceId) {
  const target=$(`#product-config-${serviceId}`);
  const names=['base_minor','per_user_minor','per_gb_minor','per_day_minor','base_stars','per_user_stars','per_gb_stars','per_day_stars','base_usd_cents','per_user_usd_cents','per_gb_usd_cents','per_day_usd_cents','min_users','max_users','min_traffic_gb','max_traffic_gb','min_days','max_days'];
  let current={};try{current=await api(`admin/products/${serviceId}/pricing`)}catch(error){if(!error.message.includes('not found')){notice(error.message);return}}
  target.innerHTML=`<form class="pricing-form">${names.map((name)=>field(name.endsWith('_minor')?name.replaceAll('_',' ').replace('minor','(Toman)'):name.replaceAll('_',' '),name,'number',!['base_stars','base_usd_cents'].includes(name),current[name]===null||current[name]===undefined?'':name.endsWith('_minor')?current[name]/10:current[name])).join('')}<label><input type="checkbox" name="enabled" ${current.enabled===false?'':'checked'}> Enabled</label><button>Save custom pricing</button></form>`;
  target.querySelector('form').onsubmit=async(event)=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target).entries());for(const name of names){values[name]=values[name]===''?null:Number(values[name]);if(name.endsWith('_minor')&&values[name]!==null){values[name]*=10;if(!Number.isSafeInteger(values[name])){notice('Invalid Toman amount');return}}}values.enabled=event.target.elements.namedItem('enabled').checked;try{await send(`admin/products/${serviceId}/pricing`,'PUT',values);notice('Custom pricing saved')}catch(error){notice(error.message)}};
}

document.querySelectorAll('[data-page]').forEach((button)=>button.onclick=()=>navigate(button.dataset.page));
$('#refresh').onclick=load;
$('#logout').onclick=async()=>{try{await send('auth/logout','POST',{});state.me=null;state.clients=null;state.nodes={};showLogin()}catch(error){notice(error.message)}};
