$('#language').onchange=async(event)=>{const language=event.target.value;try{if(state.me?.role)await send('me/language','POST',{language});window.AlartI18n.setLanguage(language);render()}catch(error){notice(error.message)}};
$('#login-language').onchange=event=>{window.AlartI18n.setLanguage(event.target.value);showLogin()};
$('#login-theme').onchange=event=>setTheme(event.target.value);
$('#panel-search').oninput=(event)=>{
  const value=event.target.value.trim().toLocaleLowerCase(),box=$('#search-results');
  if(!value){box.hidden=true;box.innerHTML='';return}
  const labels={overview:'Control center',panels:'Panels',clients:'Clients',products:'Products',payments:'Payments',referrals:'Referrals',finance:'Finance',administration:'Administration'};
  const records=[...Object.entries(labels).map(([page,label])=>({page,label})),...state.panels.map(p=>({page:'panels',label:p.name})),...(state.catalog?.services||[]).map(p=>({page:'products',label:p.name}))];
  const matches=records.filter(item=>item.label.toLocaleLowerCase().includes(value)||window.AlartI18n.t(item.label).toLocaleLowerCase().includes(value)).slice(0,8);
  box.innerHTML=matches.map(item=>`<button type="button" data-search-page="${item.page}">${escapeHtml(item.label)}<small>${escapeHtml(labels[item.page])}</small></button>`).join('')||'<p>No matching section or loaded record.</p>';
  box.hidden=false;
  box.querySelectorAll('[data-search-page]').forEach(button=>button.onclick=()=>{box.hidden=true;$('#panel-search').value='';navigate(button.dataset.searchPage)});
};
load();
